494	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
495	    debug!(
496	        "complete_subcommand: cmd={:?}, value={:?}",
497	        cmd.get_name(),
498	        value
499	    );
500	
501	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
502	        .into_iter()
503	        .filter(|x| x.get_value().starts_with(value))
504	        .collect();
505	    if cmd.is_allow_external_subcommands_set() {
506	        let external_completer = cmd.get::<SubcommandCandidates>();
507	        if let Some(completer) = external_completer {
508	            scs.extend(complete_value_candidates_str(
509	                value,
510	                completer.value_candidates(),
511	            ));
512	        }
513	    }
514	
515	    scs.sort();
516	    scs.dedup();
517	    scs
518	}
