619	fn populate_command_candidate(
620	    candidate: CompletionCandidate,
621	    cmd: &clap::Command,
622	    subcommand: &clap::Command,
623	) -> CompletionCandidate {
624	    candidate
625	        .help(subcommand.get_about().cloned())
626	        .id(Some(format!("command::{}", subcommand.get_name())))
627	        .tag(Some(
628	            cmd.get_subcommand_help_heading()
629	                .unwrap_or("Commands")
630	                .to_owned()
631	                .into(),
632	        ))
