637	/// Parse the short flags and find the first `takes_values` option.
638	///
639	/// Returns the raw leading flags, every matched argument, the first
640	/// `takes_values` option (if any), and the remaining unparsed flags.
641	fn parse_shortflags<'c, 's>(
642	    cmd: &'c clap::Command,
643	    mut short: clap_lex::ShortFlags<'s>,
644	) -> (
645	    String,
646	    Vec<&'c clap::Arg>,
647	    Option<&'c clap::Arg>,
648	    clap_lex::ShortFlags<'s>,
649	) {
650	    let takes_value_opt;
651	    let mut matched_opts = Vec::new();
652	    let mut leading_flags = String::new();
653	    // Find the first takes_values option.
654	    loop {
655	        match short.next_flag() {
656	            Some(Ok(opt)) => {
657	                leading_flags.push(opt);
658	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
659	                if let Some(opt) = opt {
660	                    matched_opts.push(opt);
661	                }
662	                if opt
663	                    .map(|o| o.get_num_args().expect("built").takes_values())
664	                    .unwrap_or(false)
665	                {
666	                    takes_value_opt = opt;
667	                    break;
668	                }
669	            }
670	            Some(Err(_)) | None => {
671	                takes_value_opt = None;
672	                break;
673	            }
674	        }
675	    }
676	
677	    (leading_flags, matched_opts, takes_value_opt, short)
678	}
